def valid_book(book):
 """The new compiler/no-ISBN exception is bound to one complete fixed profile."""
 expected=PROFILE['book']
 return set(book)==set(expected)|{'subjects'} and all(canonical_sha(book.get(k))==canonical_sha(v) for k,v in expected.items())

def validate_finite_row(row,profile):
 """Shared shape for exact reviewed secondary profiles; never an open field gate."""
 review=row.get('review',{});fixed=profile['approved'].get(review.get('approved_candidate_id'))
 need(fixed is not None and row.get('source_id')==profile['source_id'] and review.get('root_record_sha256')==profile['review_sha256'] and review.get('source_book_sha256')==profile['source_sha256'],'exact finite source/Root/candidate proof required')
 actual=[row.get('catalog_id'),row.get('field'),row.get('quantity_kind'),row.get('pdf_page_1based'),row.get('formula_display'),review.get('proposal_field_sha256')]
 need(canonical_sha(actual)==canonical_sha(fixed[:6]) and row.get('value')==fixed[7] and canonical_sha(row.get('conditions'))==canonical_sha(fixed[6]),'exact reviewed species/field/value/conditions required')
 need(row.get('unit') is row.get('hardness_scale') is None and set(profile['required_limits'])<=set(row.get('limits',[])),'literal secondary quantities and scope limits required')
 need(not {'Root_approval_pending_no_App_import','Root_approval_pending','no_App_import'}&set(row['limits']),'pending proposal cannot ship as approved evidence')
 conditions=row.get('conditions');need(isinstance(conditions,list) and all(isinstance(x,str) and len(x)<=200 for x in conditions),'finite reviewed conditions required')
 if row['field']=='formula':need(isinstance(row.get('formula_display'),str) and 0<len(row['formula_display'])<=100,'separate approved literal formula required')
 else:need('formula_display' not in row,'nonformula cannot gain a formula')
 pages=row.get('source_pages');need(isinstance(pages,list) and len(pages)==1 and isinstance(pages[0],dict),'one reviewed source page required')
 p=pages[0];need(set(p)=={'pdf_page_1based','printed_page','render_sha256'} and type(p['pdf_page_1based']) is int and profile['pages'].get(str(p['pdf_page_1based']))=={k:p[k] for k in ('printed_page','render_sha256')},'exact approved content page/render required')
 need(p['pdf_page_1based']==row['pdf_page_1based'] and p['printed_page']==row['printed_page'] and review.get('source_evidence_sha256')==canonical_sha(pages),'exact source locator proof required')

def validate_row(row):return validate_finite_row(row,PROFILE)
